CREATE DATABASE IF NOT EXISTS cineman CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cineman;
CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,phone VARCHAR(20) NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('MANAGER','SALES','CUSTOMER') NOT NULL);
CREATE TABLE members(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL UNIQUE,code VARCHAR(40) NOT NULL UNIQUE,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE movies(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(150) NOT NULL,genre VARCHAR(80) NOT NULL,duration INT NOT NULL CHECK(duration BETWEEN 1 AND 600),description TEXT NOT NULL,release_date DATE NULL,age_rating ENUM('P','K','T13','T16','T18','C') NULL,trailer_url VARCHAR(500) NULL);
CREATE TABLE rooms(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) UNIQUE NOT NULL,seat_rows INT NOT NULL CHECK(seat_rows BETWEEN 1 AND 26),seat_cols INT NOT NULL CHECK(seat_cols BETWEEN 1 AND 30));
CREATE TABLE seats(id BIGINT PRIMARY KEY AUTO_INCREMENT,room_id BIGINT NOT NULL,label VARCHAR(8) NOT NULL,UNIQUE(room_id,label),FOREIGN KEY(room_id) REFERENCES rooms(id));
CREATE TABLE shows(id BIGINT PRIMARY KEY AUTO_INCREMENT,movie_id BIGINT NOT NULL,room_id BIGINT NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,price DECIMAL(12,0) NOT NULL CHECK(price>0),FOREIGN KEY(movie_id) REFERENCES movies(id),FOREIGN KEY(room_id) REFERENCES rooms(id));
CREATE TABLE orders(id BIGINT PRIMARY KEY AUTO_INCREMENT,actor_id BIGINT NOT NULL,customer_id BIGINT NULL,request_key VARCHAR(36) NOT NULL UNIQUE,channel ENUM('ONLINE','COUNTER') NOT NULL,total DECIMAL(14,0) NOT NULL,contact_name VARCHAR(100) NULL,contact_email VARCHAR(190) NULL,contact_phone VARCHAR(20) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_id) REFERENCES users(id),FOREIGN KEY(customer_id) REFERENCES users(id));
CREATE TABLE tickets(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,show_id BIGINT NOT NULL,seat_id BIGINT NOT NULL,price DECIMAL(12,0) NOT NULL,UNIQUE(show_id,seat_id),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(show_id) REFERENCES shows(id),FOREIGN KEY(seat_id) REFERENCES seats(id));
CREATE TABLE payments(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL UNIQUE,method ENUM('SIMULATED','CASH') NOT NULL,amount DECIMAL(14,0) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id));
